function renderInventory(){const b=$('#apInventoryBody'),k=$('#apInventoryKpis');if(!b)return;const avail=state.inventory.reduce((a,x)=>a+Math.max(0,x.onHand-x.reserved),0),low=state.inventory.filter(x=>x.onHand-x.reserved<=x.low).length; if(k)k.innerHTML=[['Available',avail],['Reserved',state.inventory.reduce((a,x)=>a+x.reserved,0)],['Incoming',state.inventory.reduce((a,x)=>a+x.incoming,0)],['Low stock',low]].map(x=>`<article class="ap-card ap-kpi"><span class="ap-kpi-label">${x[0]}</span><strong>${x[1]}</strong></article>`).join(''); $('#apLowStockPill').textContent=low;
 b.innerHTML=state.inventory.map((x,i)=>`<tr><td class="mono">${x.sku}</td><td>${esc(x.name)}</td><td>${esc(x.node)}</td><td>${x.onHand}</td><td>${x.reserved}</td><td>${Math.max(0,x.onHand-x.reserved)}</td><td>${x.incoming}</td><td>${esc(x.freshness)}</td><td><span class="ap-status ${x.onHand-x.reserved<=x.low?'gold':'green'}">${x.onHand-x.reserved<=x.low?'Low':'Healthy'}</span></td><td><button class="ap-btn mini" data-stock="${i}">Adjust</button></td></tr>`).join('');$$('[data-stock]').forEach(b=>b.onclick=()=>adjustStock(+b.dataset.stock));}
