function renderWarehouses(){const g=$('#apWarehouseGrid');if(!g)return;g.innerHTML=state.warehouses.map((w,i)=>`<article class="ap-card ap-panel"><div class="ap-panel-head"><h2>${esc(w.name)}</h2><span class="ap-status green">${esc(w.ownership)}</span></div><p>${esc(w.address)}</p><div class="ap-detail-grid"><div class="ap-detail"><label>City</label><span>${esc(w.city)}</span></div><div class="ap-detail"><label>State</label><span>${w.active?'Active':'Inactive'}</span></div></div><button class="ap-btn" data-node="${i}" style="margin-top:12px">Edit node</button></article>`).join('');$$('[data-node]').forEach(b=>b.onclick=()=>editNode(+b.dataset.node));}
