function submissionHref(placement){const map={'Community Spotlight':'people-of-nariyal-sutra.html#people-community','Brand Ambassador rail':'people-of-nariyal-sutra.html#people-ambassadors','Brand Promoter rail':'people-of-nariyal-sutra.html#people-promoters','Moving People rail':'people-of-nariyal-sutra.html#people-moving','People page story':'people-of-nariyal-sutra.html#stories'};return map[placement]||'people-of-nariyal-sutra.html#people-public-worlds';}
function renderSubmissions(){const list=$('#apSubmissionList'),k=$('#apSubmissionKpis'),pill=$('#apSubmissionPill');if(!list)return;const arr=state.communitySubmissions||[],review=arr.filter(x=>x.status==='IN_REVIEW').length,approved=arr.filter(x=>x.status==='APPROVED').length,rejected=arr.filter(x=>x.status==='REJECTED').length;if(pill)pill.textContent=review;if(k)k.innerHTML=[['Awaiting review',review],['Approved',approved],['Rejected',rejected],['Publication notices',(state.notificationQueue||[]).length]].map(x=>`<article class="ap-card ap-kpi"><span class="ap-kpi-label">${x[0]}</span><strong>${x[1]}</strong></article>`).join('');list.innerHTML=arr.map(x=>`<article class="ap-submission-card"><div class="ap-submission-media">${x.blobKey?`<img src="assets/images/upload-placeholder.svg" data-local-blob-key="${esc(x.blobKey)}" alt="Customer submission from ${esc(x.name)}">`:'<div class="fallback">No local image available</div>'}</div><div><div class="ap-submission-head"><div><h3>${esc(x.name||'Customer submission')}</h3><div class="ap-submission-meta"><span>${esc(x.requestedRole||'community')}</span><span>${new Date(x.submittedAt||Date.now()).toLocaleString()}</span><span>${x.consent?'Consent confirmed':'Consent missing'}</span></div></div><span class="ap-status ${x.status==='APPROVED'?'approved':x.status==='REJECTED'?'rejected':'review'}">${esc(x.status||'IN_REVIEW')}</span></div><p class="ap-submission-story">${esc(x.story||'No story text supplied.')}</p><div class="ap-task-meta"><span>${esc(x.email||'No email')}</span><span>${esc(x.whatsapp||'No WhatsApp')}</span>${x.telegram?`<span>Telegram @${esc(x.telegram)}</span>`:''}${x.placement?`<span class="ap-v25-live-dest">VISIBLE IN: ${esc(x.placement)}</span>`:''}</div><div class="ap-submission-actions">${x.status==='IN_REVIEW'?`<button class="ap-btn primary" data-sub-approve="${x.id}">Approve & choose public destination</button><button class="ap-btn danger" data-sub-reject="${x.id}">Reject</button>`:x.status==='APPROVED'?`<button class="ap-btn" data-sub-notify="${x.id}">Preview publication message</button><a class="ap-btn primary" href="${esc(submissionHref(x.placement))}" target="_blank" rel="noopener">Open public destination ↗</a>`:''}</div></div></article>`).join('')||'<div class="ap-empty">No customer submissions yet. Use the People page “Share your coconut moment” form to test the workflow.</div>';if(MediaDB&&MediaDB.hydrate)MediaDB.hydrate(list);$$('[data-sub-approve]',list).forEach(b=>b.onclick=()=>approveSubmission(b.dataset.subApprove));$$('[data-sub-reject]',list).forEach(b=>b.onclick=()=>rejectSubmission(b.dataset.subReject));$$('[data-sub-notify]',list).forEach(b=>b.onclick=()=>previewSubmissionNotice(b.dataset.subNotify));}
function approveSubmission(id){const x=(state.communitySubmissions||[]).find(v=>v.id===id);if(!x)return;if(!x.consent)return toast('Cannot publish without explicit customer consent.');const choices=[['Community Spotlight','Community Spotlight · People page'],['Brand Ambassador rail','Brand Ambassador moving rail · People page'],['Brand Promoter rail','Brand Promoter moving rail · People page'],['Moving People rail','Moving People rail · Homepage + People page'],['People page story','People editorial story']];modal('Approve customer story',x.name||id,`<form class="ap-form" id="v25ApproveSubmission"><div class="ap-field"><label>Where will customers see this image?</label><select name="placement">${choices.map(v=>`<option value="${v[0]}">${v[1]}</option>`).join('')}</select><div class="ap-v25-destination-help">The selected destination is saved on the submission and shown back in this moderation queue after approval.</div></div><div class="ap-field"><label>Public caption</label><textarea name="caption">${esc((x.story||'').slice(0,240))}</textarea></div><label class="ap-schedule-restore"><input type="checkbox" name="email" checked><span><strong>Queue approval email</strong><small>Local preview queues the message; production provider remains a release gate.</small></span></label><label class="ap-schedule-restore"><input type="checkbox" name="whatsapp" checked><span><strong>Queue WhatsApp publication notice</strong><small>No automatic WhatsApp send occurs in local preview.</small></span></label><button class="ap-btn primary">Approve, publish to destination & queue notices</button></form>`);$('#v25ApproveSubmission').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),placement=f.get('placement'),mid='UGC-'+Date.now();state.peopleStreams=state.peopleStreams||{ambassadors:{selectedIds:[]},promoters:{selectedIds:[]},community:{selectedIds:[]}};state.media.push({id:mid,name:'Community · '+(x.name||id),cat:'People',status:'Approved',visible:true,publicAllowed:true,storyAllowed:true,homepageAllowed:placement==='Moving People rail',brandFit:'Strong',placement,faceGroup:mid,localBlobKey:x.blobKey||null,src:'assets/images/upload-placeholder.svg',thumb:'assets/images/upload-placeholder.svg',version:1,versions:[{version:1,localBlobKey:x.blobKey||null,at:new Date().toISOString()}],communitySubmissionId:id,caption:f.get('caption'),publicRole:placement==='Brand Ambassador rail'?'ambassador':placement==='Brand Promoter rail'?'promoter':'community'});if(placement==='Moving People rail')state.faceMarquee.selectedIds=[...(state.faceMarquee.selectedIds||[]),mid];if(placement==='Community Spotlight')state.peopleStreams.community.selectedIds=[...(state.peopleStreams.community.selectedIds||[]),mid];if(placement==='Brand Ambassador rail')state.peopleStreams.ambassadors.selectedIds=[...(state.peopleStreams.ambassadors.selectedIds||[]),mid];if(placement==='Brand Promoter rail')state.peopleStreams.promoters.selectedIds=[...(state.peopleStreams.promoters.selectedIds||[]),mid];if(placement==='People page story'){let st=(state.stories||[]).find(v=>v.id==='ST-PEOPLE');if(st)st.mediaIds=[...(st.mediaIds||[]),mid];}x.status='APPROVED';x.placement=placement;x.publicMediaId=mid;x.approvedAt=new Date().toISOString();x.notificationState='Queued';state.notificationQueue=state.notificationQueue||[];const body=`Your Nariyal Sutra story has been approved and is now visible in ${placement}. Thank you for sharing your coconut moment with our community.`;if(f.get('email')==='on'&&x.email)state.notificationQueue.push({id:'N-'+Date.now()+'E',channel:'Email',audience:x.email,subject:'Your Nariyal Sutra story is live',body,state:'Queued · local preview',submissionId:id});if(f.get('whatsapp')==='on'&&x.whatsapp)state.notificationQueue.push({id:'N-'+Date.now()+'W',channel:'WhatsApp',audience:x.whatsapp,subject:'Your story is live',body,state:'Queued · local preview',submissionId:id});closeModal();save('Community submission approved and published',id);};}
