function renderMedia(){const g=$('#apMediaGrid');if(!g)return;const selects=$$('.ap-view[data-view="media"] .ap-toolbar select'),stateFilter=selects[1]?.value||'Working set';let arr=state.media;if(stateFilter==='Working set')arr=arr.filter(m=>!['Rejected','Archived'].includes(m.status));else if(stateFilter!=='All states')arr=arr.filter(m=>m.status===stateFilter);g.innerHTML=arr.map(mediaCard).join('');bindMediaActions(g);if(MediaDB&&MediaDB.hydrate)MediaDB.hydrate(g);hydrateMediaPreviews(g);}
