function openMediaState(m){modal('Media lifecycle',m.id,`<div class="ap-form"><div class="ap-field"><label>Status</label><select id="v21MediaState">${['Approved','Needs review','Needs enhancement','Rejected','Archived'].map(v=>`<option ${v===m.status?'selected':''}>${v}</option>`).join('')}</select></div><label class="ap-radio-card"><input type="checkbox" id="v21MediaVisible" ${m.visible?'checked':''}><span><strong>Visible where eligible</strong><small>Rejected/archived still remain excluded from public surfaces.</small></span></label><button class="ap-btn primary" id="v21MediaStateSave">Save lifecycle</button></div>`);$('#v21MediaStateSave').onclick=()=>{m.status=$('#v21MediaState').value;m.visible=$('#v21MediaVisible').checked;closeModal();save('Media lifecycle updated',m.id);};}
