function scheduleMediaPicker(selected){const arr=(state.media||[]).filter(m=>m.status==='Approved'&&m.visible&&!['Rejected','Archived'].includes(m.status));return `<div class="ap-schedule-media" id="v23ScheduleMedia">${arr.map(m=>`<label><input type="radio" name="mediaId" value="${esc(m.id)}" ${m.id===selected?'checked':''}><img src="${esc(m.localBlobKey?'assets/images/upload-placeholder.svg':(m.thumb||m.src))}" ${m.localBlobKey?`data-local-blob-key="${esc(m.localBlobKey)}"`:''} data-media-preview="${esc(m.id)}" alt="${esc(m.name)}"><span>${esc(m.id)}</span><small>${esc(m.name)}</small></label>`).join('')}</div>`;}
function renderSchedule(){const e=$('#apCalendar');if(!e)return;const now=Date.now(),items=state.schedule||[],active=items.filter(x=>x.state==='Scheduled'&&new Date(x.startAt||x.date||0).getTime()<=now&&(!x.endAt||new Date(x.endAt).getTime()>=now)).length,upcoming=items.filter(x=>x.state==='Scheduled'&&new Date(x.startAt||x.date||0).getTime()>now).length,expired=items.filter(x=>x.endAt&&new Date(x.endAt).getTime()<now).length,sum=$('#apScheduleSummary');if(sum)sum.innerHTML=[['Active now',active],['Upcoming',upcoming],['Ended',expired],['Restore default',items.filter(x=>x.restoreDefault!==false).length]].map(x=>`<div><small>${x[0]}</small><strong>${x[1]}</strong></div>`).join('');const y=calendarDate.getFullYear(),m=calendarDate.getMonth();$('#apCalendarTitle').textContent=new Intl.DateTimeFormat('en',{month:'long',year:'numeric'}).format(calendarDate);const first=new Date(y,m,1),days=new Date(y,m+1,0).getDate(),offset=first.getDay();let html=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="ap-dayname">${d}</div>`).join('');for(let i=0;i<offset;i++)html+='<div class="ap-day muted"></div>';for(let d=1;d<=days;d++){const iso=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,events=items.filter(x=>(x.startAt||x.date||'').slice(0,10)===iso);html+=`<div class="ap-day"><b>${d}</b>${events.map(x=>`<button class="ap-event" data-event="${x.id}">${esc(x.title)}<br><small>${esc((scheduleTargets().find(t=>t[0]===x.sectionId)||['','Section'])[1])}</small></button>`).join('')}<button class="ap-day-add" data-date="${iso}">＋</button></div>`;}e.innerHTML=html;$$('[data-date]').forEach(b=>b.onclick=()=>newSchedule(b.dataset.date));$$('[data-event]').forEach(b=>b.onclick=()=>editSchedule(b.dataset.event));}
function scheduleForm(item,date){const start=item?.startAt||`${date}T09:00`,end=item?.endAt||`${date}T18:00`,target=item?.sectionId||'homepage-origin',media=item?.mediaId||'M-ORIGIN-01';return `<form class="ap-form" id="v23ScheduleForm"><div class="ap-field"><label>Campaign / schedule title</label><input name="title" required value="${esc(item?.title||'')}"></div><div class="ap-field"><label>Where should this image appear?</label><select name="sectionId">${scheduleTargets().map(x=>`<option value="${x[0]}" ${x[0]===target?'selected':''}>${x[1]}</option>`).join('')}</select></div><div class="ap-field"><label>Select approved image</label>${scheduleMediaPicker(media)}</div><div class="ap-schedule-window"><div class="ap-field"><label>Show from · date & time</label><input name="startAt" type="datetime-local" required value="${esc(start)}"></div><div class="ap-field"><label>Remove at · date & time</label><input name="endAt" type="datetime-local" value="${esc(end)}"></div></div><label class="ap-schedule-restore"><input type="checkbox" name="restore" ${item?.restoreDefault===false?'':'checked'}><span><strong>Restore the section's normal image after removal</strong><small>No replacement is hard-coded after the end time; the baseline/default section media becomes visible again.</small></span></label><div class="ap-field"><label>Internal notes</label><textarea name="notes">${esc(item?.notes||'')}</textarea></div><button class="ap-btn primary">${item?'Save schedule':'Schedule content'}</button></form>`;}
function scheduleOverlap(sectionId,startAt,endAt,ignoreId){const start=new Date(startAt).getTime(),end=endAt?new Date(endAt).getTime():Number.POSITIVE_INFINITY;return (state.schedule||[]).find(x=>x.state==='Scheduled'&&x.id!==ignoreId&&x.sectionId===sectionId&&Math.max(start,new Date(x.startAt||x.date||0).getTime())<Math.min(end,x.endAt?new Date(x.endAt).getTime():Number.POSITIVE_INFINITY));}
function newSchedule(date){modal('Schedule content','Image + section + exact publish/removal window',scheduleForm(null,date));if(MediaDB&&MediaDB.hydrate)MediaDB.hydrate($('#v23ScheduleForm'));$('#v23ScheduleForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),mediaId=f.get('mediaId');if(!mediaId)return toast('Choose an approved image.');const start=f.get('startAt'),end=f.get('endAt');if(end&&new Date(end)<=new Date(start))return toast('Removal time must be after the start time.');const clash=scheduleOverlap(f.get('sectionId'),start,end,null);if(clash)return toast('Schedule conflict: '+clash.title+' already uses this section in that time window.');state.schedule.push({id:'SCH-'+Date.now(),title:f.get('title'),state:'Scheduled',page:String(f.get('sectionId')).split('-')[0],sectionId:f.get('sectionId'),mediaId,startAt:start,endAt:end,restoreDefault:f.get('restore')==='on',notes:f.get('notes')});closeModal();save('Schedule item created',mediaId);};}
function editSchedule(id){const item=(state.schedule||[]).find(x=>x.id===id);if(!item)return;const date=(item.startAt||item.date||new Date().toISOString()).slice(0,10);modal('Edit schedule',id,scheduleForm(item,date)+`<button type="button" class="ap-btn danger" id="v23ScheduleDelete" style="margin-top:10px">Cancel scheduled item</button>`);if(MediaDB&&MediaDB.hydrate)MediaDB.hydrate($('#apModalBody'));$('#v23ScheduleForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),start=f.get('startAt'),end=f.get('endAt');if(end&&new Date(end)<=new Date(start))return toast('Removal time must be after the start time.');const clash=scheduleOverlap(f.get('sectionId'),start,end,item.id);if(clash)return toast('Schedule conflict: '+clash.title+' already uses this section in that time window.');Object.assign(item,{title:f.get('title'),sectionId:f.get('sectionId'),mediaId:f.get('mediaId'),startAt:start,endAt:end,restoreDefault:f.get('restore')==='on',notes:f.get('notes'),state:'Scheduled'});closeModal();save('Schedule item updated',id);};$('#v23ScheduleDelete').onclick=()=>{state.schedule=state.schedule.filter(x=>x.id!==id);closeModal();save('Schedule item cancelled',id);};}
function renderTeam(){const b=$('#apTeamBody'),list=$('#apTaskList');if(!b)return;const role=currentRole(),manage=['Owner','Admin'].includes(role);b.innerHTML=state.teamMembers.map((m,i)=>`<tr><td>${esc(m.name)}</td><td>${esc(m.email)}</td><td>${esc(m.role)}</td><td><span class="ap-team-state ${m.status==='Suspended'?'suspended':m.status!=='Active'?'pending':''}">${esc(m.status)}</span></td><td>${esc(m.inviteStatus||'—')}</td><td>${manage?`<button class="ap-btn mini" data-team="${i}">Manage</button>`:'Read only'}</td></tr>`).join('');if(list)list.innerHTML=state.tasks.map(t=>`<div class="ap-list-item"><span class="ap-list-dot"></span><div><strong>${esc(t.title)}</strong><span>${esc(t.owner)} · due ${esc(t.due)} · ${esc(t.state)}</span></div></div>`).join('');$$('[data-team]').forEach(x=>x.onclick=()=>manageTeam(+x.dataset.team));$('#apTeamInvite').disabled=!manage;}
function manageTeam(i){const m=state.teamMembers[i],actor=currentRole();const roles=actor==='Owner'?['Owner','Admin','Manager','Operations','Content','Support','Sales']:['Manager','Operations','Content','Support','Sales'];modal('Manage staff access',m.name,`<form class="ap-form" id="v21TeamForm"><div class="ap-field"><label>Role</label><select name="role">${roles.map(v=>`<option ${v===m.role?'selected':''}>${v}</option>`).join('')}</select></div><div class="ap-field"><label>Status</label><select name="status">${['Active','Suspended','Revoked'].map(v=>`<option ${v===m.status?'selected':''}>${v}</option>`).join('')}</select></div><button class="ap-btn primary">Save access</button></form>`);$('#v21TeamForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),next=f.get('role');if(actor!=='Owner'&&['Owner','Admin'].includes(next))return toast('Only Owner can assign Owner/Admin roles.');m.role=next;m.status=f.get('status');closeModal();save('Staff access updated',m.email);};}
function renderAudit(){const view=$('.ap-view[data-view="audit"] .ap-list');if(!view)return;view.innerHTML=(state.audit||[]).slice(0,40).map(a=>`<div class="ap-list-item"><span class="ap-list-dot"></span><div><strong>${esc(a.action)}</strong><span>${esc(a.actor||'Local preview')} · ${new Date(a.at).toLocaleString()}${a.target?' · '+esc(a.target):''}</span></div></div>`).join('');}
