 $('#v21FaceAdd').onclick=()=>{const id=$('#v21FaceAddSelect').value;if(!id)return;state.faceMarquee.selectedIds=[...(state.faceMarquee.selectedIds||[]),id];save('People image added',id);};
 $$('[data-face-move]').forEach(b=>b.onclick=()=>{const a=state.faceMarquee.selectedIds||[],i=a.indexOf(b.dataset.faceId),j=b.dataset.faceMove==='up'?i-1:i+1;if(i<0||j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];save('People image order updated',b.dataset.faceId);});
