function renderFaceControlInPages(){const e=$('#apPeopleSectionControls');if(!e)return;const f=state.faceMarquee||{};const places=[['after-collection','After product collection'],['after-people-teaser','After People teaser · current'],['before-story-worlds','Before Story Worlds'],['before-how-to-order','Before How To Order'],['before-order','Before Order form']];e.innerHTML=`<div class="ap-toggle-row"><div><strong>Show moving People section</strong><div class="ap-help">Hide/show without deleting the full-picture selection.</div></div><input type="checkbox" id="v22PeopleVisible" ${f.enabled?'checked':''}></div><div class="ap-row"><div class="ap-field"><label>Homepage placement</label><select id="v22PeoplePlacement">${places.map(x=>`<option value="${x[0]}" ${f.placement===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div><div class="ap-field"><label>Background preset</label><select id="v22PeoplePreset"><option value="brand">Brand green</option><option value="forest">Deep forest</option><option value="black">Near black</option><option value="custom">Custom</option></select></div></div><div class="ap-row"><div class="ap-field"><label>Background start</label><input type="color" id="v22PeopleBg1" value="${esc(f.background||'#061004')}"></div><div class="ap-field"><label>Background end</label><input type="color" id="v22PeopleBg2" value="${esc(f.background2||'#020801')}"></div></div><div class="ap-row"><div class="ap-field"><label>Accent</label><input type="color" id="v22PeopleAccent" value="${esc(f.accent||'#d4a843')}"></div><div class="ap-field"><label>Edge fade</label><select id="v22PeopleFade"><option value="yes" ${f.edgeFade!==false?'selected':''}>On</option><option value="no" ${f.edgeFade===false?'selected':''}>Off</option></select></div></div><div class="ap-v22-live-preview" id="v22PeopleStylePreview"><span>LIVE SECTION PREVIEW</span><strong>${esc(f.title||'People, moments & the Nariyal Sutra story')}</strong><small>${esc(f.placement||'after-people-teaser')}</small></div><div class="ap-head-actions" style="margin-top:12px"><button class="ap-btn" id="v22OpenMedia">Open Media Library</button><button class="ap-btn primary" id="v22SavePeopleSection">Save section design & placement</button></div>`;const preset=$('#v22PeoplePreset'),bg1=$('#v22PeopleBg1'),bg2=$('#v22PeopleBg2'),accent=$('#v22PeopleAccent'),prev=$('#v22PeopleStylePreview');function preview(){prev.style.setProperty('--pbg1',bg1.value);prev.style.setProperty('--pbg2',bg2.value);prev.style.setProperty('--pacc',accent.value);}function applyPreset(v){if(v==='brand'){bg1.value='#061004';bg2.value='#020801';accent.value='#d4a843';}if(v==='forest'){bg1.value='#0b2110';bg2.value='#031008';accent.value='#e0b24d';}if(v==='black'){bg1.value='#080b08';bg2.value='#010201';accent.value='#d4a843';}preview();}preset.onchange=()=>{if(preset.value!=='custom')applyPreset(preset.value)};[bg1,bg2,accent].forEach(x=>x.oninput=()=>{preset.value='custom';preview();});preview();$('#v22OpenMedia').onclick=()=>openView('media');$('#v22SavePeopleSection').onclick=()=>{Object.assign(state.faceMarquee,{enabled:$('#v22PeopleVisible').checked,placement:$('#v22PeoplePlacement').value,background:bg1.value,background2:bg2.value,accent:accent.value,edgeFade:$('#v22PeopleFade').value==='yes'});save('People section design and placement updated','people-marquee');};}
