function renderTracking(){const d=state.deliveryLive;$('#apTrackStatus').textContent=d.status.replaceAll('_',' ');$('#apTrackUpdate').textContent=d.customerUpdate;$('#apTrackPartner').textContent=d.partnerName;$('#apTrackEta').textContent=d.eta;$('#apTrackLocation').textContent=d.locationLabel;}
function tileUrl(mode){return mode==='satellite'?'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}':mode==='terrain'?'https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png':'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png';}
function pinIcon(){return L.divIcon({className:'v21-pin-icon-wrap',html:'<div class="v21-map-pin"><span>🥥</span><i></i></div>',iconSize:[46,58],iconAnchor:[23,54],popupAnchor:[0,-48]});}
async function reverse(lat,lng){try{const r=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${encodeURIComponent(lat)}&lon=${encodeURIComponent(lng)}`);if(r.ok){const j=await r.json();if(j.display_name)return j.display_name;}}catch(e){}return `Pinned location · ${lat.toFixed(6)}, ${lng.toFixed(6)}`;}
async function searchPlace(q){const local={jabalpur:[23.1815,79.9864,'Jabalpur, Madhya Pradesh'],ranjhi:[23.1987,80.0192,'Ranjhi, Jabalpur, Madhya Pradesh'],virar:[19.4559,72.8114,'Virar, Maharashtra'],mumbai:[19.076,72.8777,'Mumbai, Maharashtra']};const key=Object.keys(local).map(k=>[k,q.toLowerCase().indexOf(k)]).filter(x=>x[1]>=0).sort((a,b)=>a[1]-b[1])[0]?.[0];if(key){const x=local[key];return {lat:x[0],lng:x[1],label:x[2]};}try{const r=await fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&q='+encodeURIComponent(q));if(r.ok){const a=await r.json();if(a[0])return {lat:+a[0].lat,lng:+a[0].lon,label:a[0].display_name};}}catch(e){}return null;}
function mapInputs(){const f=$('#apDeliveryForm');return {lat:f?.elements.lat,lng:f?.elements.lng,location:f?.elements.location};}
async function setPin(lat,lng,label,source){const d=state.deliveryLive,inp=mapInputs();d.lat=+lat;d.lng=+lng;d.locationLabel=label||await reverse(+lat,+lng);if(inp.lat)inp.lat.value=(+lat).toFixed(6);if(inp.lng)inp.lng.value=(+lng).toFixed(6);if(inp.location)inp.location.value=d.locationLabel;$('#apAdminDeliveryCoords').textContent=`${(+lat).toFixed(6)}, ${(+lng).toFixed(6)}`;$('#apAdminDeliveryMapStatus').textContent=(source==='drag'?'Pin moved · address refreshed':source==='search'?'Address found · fine-tune the pin if needed':'Pin updated')+' · '+d.locationLabel;$('#apPinConfidence').textContent=source==='drag'?'Precise pin selected. Save & sync when ready.':'Drag the coconut pin to the exact entrance if needed.';$('#apDeliveryOpenGoogle').onclick=()=>window.open('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(lat+','+lng),'_blank','noopener');renderTracking();}
function initMap(){const d=state.deliveryLive,el=$('#apAdminDeliveryMap'),inp=mapInputs();if(inp.lat&&!inp.lat.value)inp.lat.value=d.lat;if(inp.lng&&!inp.lng.value)inp.lng.value=d.lng;if(inp.location)inp.location.value=d.locationLabel;if(!el)return;if(map){setTimeout(()=>map.invalidateSize(true),60);return;}if(!window.L){el.innerHTML='<div class="v21-offline-map"><div class="v21-offline-streets"></div><button type="button" class="v21-offline-pin" aria-label="Delivery pin">🥥</button><span>Map imagery unavailable. Location selection still works through address search and coordinates.</span></div>';$('#apAdminDeliveryMapStatus').textContent='Map imagery unavailable. Enter/search address and coordinates.';setPin(d.lat,d.lng,d.locationLabel);return;}
 map=L.map(el,{zoomControl:true}).setView([d.lat,d.lng],14);tile=L.tileLayer(tileUrl(mapMode),{maxZoom:19,attribution:'Map data / imagery providers'}).addTo(map);marker=L.marker([d.lat,d.lng],{draggable:true,icon:pinIcon(),autoPan:true}).addTo(map);marker.bindTooltip('Drag me to the exact delivery point',{direction:'top',offset:[0,-38]});marker.on('dragstart',()=>{$('#apPinConfidence').textContent='Moving pin…';});marker.on('dragend',async()=>{const p=marker.getLatLng();await setPin(p.lat,p.lng,await reverse(p.lat,p.lng),'drag');});map.on('click',async e=>{marker.setLatLng(e.latlng);await setPin(e.latlng.lat,e.latlng.lng,await reverse(e.latlng.lat,e.latlng.lng),'drag');});setTimeout(()=>map.invalidateSize(true),100);setPin(d.lat,d.lng,d.locationLabel);
}
function syncDeliveryForm(){const d=state.deliveryLive,f=$('#apDeliveryForm');f.elements.status.value=d.status;f.elements.eta.value=d.eta;f.elements.partner.value=d.partnerName;f.elements.vehicle.value=d.vehicle;f.elements.location.value=d.locationLabel;f.elements.lat.value=d.lat;f.elements.lng.value=d.lng;f.elements.update.value=d.customerUpdate;(f.elements.internalNote||f.elements.internal).value=d.internalNote;}
function saveDelivery(){const f=$('#apDeliveryForm'),d=state.deliveryLive;Object.assign(d,{status:f.elements.status.value,eta:f.elements.eta.value,partnerName:f.elements.partner.value,vehicle:f.elements.vehicle.value,locationLabel:f.elements.location.value,lat:+f.elements.lat.value,lng:+f.elements.lng.value,customerUpdate:f.elements.update.value,internalNote:(f.elements.internalNote||f.elements.internal).value});save('Delivery truth saved & customer projection refreshed',d.orderId);renderTracking();}
